@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

<div class="container mt-4">
    @if (recipe is not null)
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            </ol>
        </nav>

        <h1>@recipe.Title</h1>
        <p class="text-muted">Category: @recipe.Category</p>

        <div class="row">
            <div class="col-md-8">
                <div class="card mb-4">
                    <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                    <div class="card-body">
                        <ul class="list-unstyled">
                            @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                            {
                                <li>• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
                    <div class="card-body">
                        @foreach (var step in recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>

            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">⭐ Rating</h5></div>
                    <div class="card-body text-center">
                        <p class="fs-4">@recipe.AverageRating.ToString("F1") / 5.0</p>
                        <p class="text-muted">@recipe.RatingCount ratings</p>
                        <hr />
                        <p><strong>Rate this recipe:</strong></p>
                        <StarRating RecipeId="@recipe.Id" />
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="fs-3" style="cursor: pointer;" @onclick="() => Rate(star)">
            @(star <= selectedRating ? "★" : "☆")
        </span>
    }
</div>

@if (submitted)
{
    <div class="alert alert-success mt-2">Thanks for rating!</div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

