@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit Your Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@model.Title</strong>" has been added to the @model.Category category.</p>
            <a href="/category/@model.Category" class="btn btn-primary">View Category</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label class="form-label">Recipe Title</label>
                <InputText class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label class="form-label">Category</label>
                <InputSelect class="form-select" @bind-Value="model.Category">
                    <option value="">-- Select Category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label class="form-label">Ingredients (one per line)</label>
                <InputTextArea class="form-control" rows="6" @bind-Value="model.Ingredients"
                    placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
            </div>

            <div class="mb-3">
                <label class="form-label">Steps (one per line)</label>
                <InputTextArea class="form-control" rows="6" @bind-Value="model.Steps"
                    placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. Add wet ingredients." />
            </div>

            <button type="submit" class="btn btn-success btn-lg"
                disabled="@(string.IsNullOrWhiteSpace(model.Title) || string.IsNullOrWhiteSpace(model.Category))">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private Recipe model = new();
    private bool submitted;

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(model.Title) && !string.IsNullOrWhiteSpace(model.Category))
        {
            RecipeService.SubmitRecipe(model);
            submitted = true;
        }
    }

    private void Reset()
    {
        model = new Recipe();
        submitted = false;
    }
}
